<?php require 'config.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([trim($_POST['email'])]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];header('Location: user_dashboard.php');exit;}$msg='Invalid email or password.';}?><h1>User Login</h1><p><?=h($msg)?></p><form method="post"><input type="email" name="email" placeholder="Email" required><br><input type="password" name="password" placeholder="Password" required><br><button>Login</button></form><a href="register.php">Register</a>